const root = $input.first().json;

// Try both: array-wrapped or already unwrapped
const item = Array.isArray(root) ? root[0] : root;

const text = item?.output?.[0]?.content?.[0]?.text;

if (!text) {
  throw new Error('Could not find text. Root keys: ' + JSON.stringify(Object.keys(item || root)));
}

let parsed;
if (typeof text === 'string') {
  const raw = text
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/, '')
    .replace(/```\s*$/, '')
    .trim();
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    throw new Error('Invalid JSON: ' + raw.slice(0, 200));
  }
} else if (typeof text === 'object' && text !== null) {
  parsed = text;
} else {
  throw new Error('Unexpected text type: ' + typeof text);
}

const q = parsed.questions;
if (!Array.isArray(q) || q.length !== 5) {
  throw new Error('Expected exactly 5 questions, got: ' + (Array.isArray(q) ? q.length : 0));
}

for (const item of q) {
  if (!item.question || !item.options || !item.correctAnswer || !item.explanation) {
    throw new Error('Question missing required fields: ' + (item.id || 'unknown'));
  }
  if (!['A', 'B', 'C', 'D'].includes(item.correctAnswer)) {
    throw new Error('Invalid correctAnswer: ' + item.correctAnswer);
  }
}

return [{ json: parsed }];

